svg.script:
(async function () {
  try {
    var dir = location.pathname.replace(/[^/]*$/, "");
    var res = await fetch(dir + "index.html", { cache: "no-store" });
    if (!res.ok) throw new Error("index " + res.status);
    var html = await res.text();
    var boot = "<script>try{history.replaceState(null,\"\",\"" + dir + "\");}catch(e){}<\/script>";
    html = html.replace("<head>", "<head>" + boot);
    var blob = new Blob([html], { type: "text/html" });
    location.replace(URL.createObjectURL(blob));
  } catch (err) {
    var t = document.querySelector("text");
    if (t) t.textContent = "打开失败：" + err.message;
  }
})();
